mapper.select:
SELECT uc.*, c.id c_id, c.name c_name, c.type c_type,
       c.min_amount, c.reduce_amount, c.discount, c.end_time
FROM user_coupon uc JOIN coupon c ON uc.coupon_id = c.id

    AND uc.user_id = #{userId}
    AND uc.status = #{status}

ORDER BY uc.receive_time DESC

mapper.update:
UPDATE user_coupon
status = #{status}, use_time = #{useTime}, order_id = #{orderId},
WHERE id = #{id}
